import type { HTMLAttributes } from "astro/types"

import { cn } from "@/lib/utils"

type Props = HTMLAttributes<"div"> & {
  heading?: string
  value?: string
  forceMount?: boolean
}

const { class: className, heading, value, forceMount, ...props } = Astro.props
---

<div
  data-slot="command-group"
  data-value={value}
  data-force-mount={forceMount ? "true" : undefined}
  class={cn("text-foreground [&_[data-slot=command-group-heading]]:text-muted-foreground overflow-hidden p-1.5 [&_[data-slot=command-group-heading]]:px-3 [&_[data-slot=command-group-heading]]:py-2 [&_[data-slot=command-group-heading]]:text-xs [&_[data-slot=command-group-heading]]:font-semibold [&_[data-slot=command-group-heading]]:uppercase [&_[data-slot=command-group-heading]]:tracking-wider", className)}
  {...props}
>
  {heading && <div data-slot="command-group-heading">{heading}</div>}
  <slot />
</div>

---
import type { HTMLAttributes } from "astro/types"
import CheckIcon from "@lucide/astro/icons/check"

import { cn } from "@/lib/utils"

type Props = HTMLAttributes<"a"> & {
  disabled?: boolean
  href?: string
  value?: string
  label?: string
  keywords?: string | string[]
  forceMount?: boolean
}

const {
  class: className,
  disabled,
  href,
  value,
  label,
  keywords,
  forceMount,
  ...props
} = Astro.props

const Tag = href ? "a" : "div"
const keywordsValue = Array.isArray(keywords) ? keywords.join(", ") : keywords
---

<Tag
  data-slot="command-item"
  data-disabled={disabled ? "true" : undefined}
  data-value={value}
  data-label={label}
  data-keywords={keywordsValue}
  data-force-mount={forceMount ? "true" : undefined}
  href={href}
  class={cn(
    "data-selected:bg-muted data-selected:text-foreground data-selected:*:[svg]:text-foreground relative flex cursor-default items-center gap-2 rounded-none px-3 py-2 text-sm outline-hidden select-none in-data-[slot=dialog-content]:rounded-none [&_svg:not([class*='size-'])]:size-3.5 group/command-item data-[disabled=true]:pointer-events-none data-[disabled=true]:opacity-50 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&[href]]:cursor-pointer [&[href]]:no-underline",
    className
  )}
  {...props}
>
  <slot />
  <CheckIcon class="ml-auto opacity-0 group-has-data-[slot=command-shortcut]/command-item:hidden group-data-selected/command-item:opacity-100" />
</Tag>
